// NEW F61 finite twist-assisted pairing/source-scalar reduction preflight; no timing/IC claim.
#include <array>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <optional>
#include <iostream>
#include <fstream>
#include <sstream>
#include <stdexcept>
int mod(int x){x%=61;return x<0?x+61:x;}int power(int x,int n){int r=1;for(;n;n>>=1,x=mod(x*x))if(n&1)r=mod(r*x);return r;}
void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
struct F{int a,b;F(int x=0,int y=0):a(mod(x)),b(mod(y)){}auto operator<=>(const F&)const=default;};
F operator+(F x,F y){return{ x.a+y.a,x.b+y.b};}F operator-(F x,F y){return{x.a-y.a,x.b-y.b};}F operator-(F x){return{-x.a,-x.b};}F operator*(F x,F y){return{x.a*y.a+59*x.b*y.b,x.a*y.b+x.b*y.a};}
F inverse(F x){int n=mod(x.a*x.a-59*x.b*x.b);need(n!=0,"zero field inverse");int v=power(n,59);return{x.a*v,-x.b*v};}F operator/(F x,F y){return x*inverse(y);}F pow(F x,int n){F r(1);for(;n;n>>=1,x=x*x)if(n&1)r=r*x;return r;}int encode(F x){return x.a+61*x.b;}
struct P{F x,y;bool o=true;auto operator<=>(const P&)const=default;};P neg(P p){if(!p.o)p.y=-p.y;return p;}
bool on(P p,int a,int b){return p.o||p.y*p.y==p.x*p.x*p.x+F(a)*p.x+F(b);}
P add(P p,P q,int a=21){if(p.o)return q;if(q.o)return p;if(p.x==q.x&&p.y+q.y==F())return{};F l=p.x==q.x?(F(3)*p.x*p.x+F(a))/(F(2)*p.y):(q.y-p.y)/(q.x-p.x);F x=l*l-p.x-q.x;return{x,l*(p.x-x)-p.y,false};}
P mul(P p,int n,int a=21){P r;for(;n;n>>=1,p=add(p,p,a))if(n&1)r=add(r,p,a);return r;}
P chi(P p){return p.o?p:P{p.x/F(59),p.y/F(0,59),false};}
std::optional<F> line(P p,P q,P at){if(p.o||q.o||at.o)return{};if(p.x==q.x&&p.y+q.y==F()){F z=at.x-p.x;return z==F()?std::nullopt:std::optional<F>(z);}F den=p.x==q.x?F(2)*p.y:q.x-p.x;if(den==F())return{};F l=p.x==q.x?(F(3)*p.x*p.x+F(21))/den:(q.y-p.y)/den;F num=at.y-p.y-l*(at.x-p.x);P sum=add(p,q);F v=sum.o?F(1):at.x-sum.x;if(num==F()||v==F())return{};return num/v;}
std::optional<F> miller(P p,P at){if(p.o||at.o)return{};F f(1);P v=p;for(int bit=8;bit;bit>>=1){auto z=line(v,v,at);if(!z)return{};f=f*f*(*z);v=add(v,v);if(31&bit){z=line(v,p,at);if(!z)return{};f=f*(*z);v=add(v,p);}}need(v.o,"wrong31 Miller endpoint");return f;}
std::optional<F> pairing(P p,P q){if(p.o||q.o)return F(1);auto a=miller(p,q),b=miller(q,p);if(!a||!b)return{};return -(*a/ *b);}
std::optional<F> shifted(P p,P q,P s){if(p.o||q.o)return F(1);auto a=miller(p,add(q,s)),b=miller(p,s),c=miller(q,neg(s)),d=miller(q,add(p,neg(s)));if(!a||!b||!c||!d)return{};return (*a/ *b)*(*c/ *d);}
std::vector<P> group(P g,int a,int b){std::vector<P>v{P{}};P p;for(int n=1;n<31;n++){p=add(p,g,a);need(on(p,a,b)&&!p.o,"bad subgroup cycle");v.push_back(p);}need(add(p,g,a).o,"wrong order31");std::sort(v.begin()+1,v.end());need(std::set<P>(v.begin(),v.end()).size()==31,"duplicate subgroup point");return v;}
int field_bsgs(F g,F z){need(g!=F(1)&&pow(g,31)==F(1)&&pow(z,31)==F(1),"field subgroup");std::map<F,int>baby;F p(1);for(int j=0;j<6;j++){baby[p]=j;p=p*g;}F step=pow(g,25),at=z;for(int i=0;i<6;i++){auto it=baby.find(at);if(it!=baby.end()){int k=6*i+it->second;if(k<31&&pow(g,k)==z)return k;}at=at*step;}throw std::runtime_error("field BSGS exhausted");}
int recover(P unknown,P generator,P partner,F field_generator){auto z=pairing(unknown,partner);need(z.has_value(),"unknown point pairing undefined");int k=field_bsgs(field_generator,*z);need(mul(generator,k)==unknown,"ORIGINAL source scalar check");return k;}
void point(P p){std::cout<<(p.o?-1:encode(p.x))<<' '<<(p.o?-1:encode(p.y));}
int main(int argc,char**argv){try{
if(argc==5&&std::string(argv[1])=="mutate"){std::ifstream in(argv[2]);need(bool(in),"mutator input");std::vector<std::vector<std::string>> ls;std::string line_;while(std::getline(in,line_)){std::istringstream row(line_);std::vector<std::string> v;std::string v_;while(row>>v_)v.push_back(v_);ls.push_back(v);}auto locate=[&](std::string key){for(size_t i=0;i<ls.size();i++)if(ls[i][0]==key)return i;throw std::runtime_error("missing row");};std::string mode=argv[4];auto old=ls;size_t gen=locate("GEN"),header=locate("CM61PAIR");if(mode=="source")ls[header][3]="20";else if(mode=="delta")ls[header][2]="58";else if(mode=="partner")ls[gen][6]=std::to_string(61*27);else if(mode=="same-subgroup-partner"){ls[gen][5]=ls[gen][1];ls[gen][6]=ls[gen][2];}else if(mode=="generator"){bool done=false;for(auto&v:ls)if(v[0]=="PAIR"&&v[9]!="1"&&v[9]!=ls[gen][7]){ls[gen][7]=v[9];done=true;break;}need(done,"generator mutation");}else if(mode=="pair-value"){bool done=false;for(auto&v:ls)if(v[0]=="PAIR"&&v[9]!="1"){v[9]="1";done=true;break;}need(done,"pair mutation");}else if(mode=="missing-pair"){for(size_t i=ls.size();i-->0;)if(ls[i][0]=="PAIR"){ls.erase(ls.begin()+i);break;}}else if(mode=="scalar"){bool done=false;for(auto&v:ls)if(v[0]=="REC"&&v[2]!="-1"){v[5]="0";done=true;break;}need(done,"scalar mutation");}else if(mode=="same-source")ls[locate("SAME")][1]=ls[gen][7];else if(mode=="wrong-subgroup"){auto&i=ls[locate("WRONG")];i[1]=ls[gen][3];i[2]=ls[gen][4];i[3]=ls[gen][5];i[4]=ls[gen][6];}else if(mode=="hom-count")ls[locate("CHECK")][3]="0";else if(mode=="degree")ls[locate("DEGREE")][1]="0";else throw std::runtime_error("unknown mutation");need(ls!=old,"unchanged mutation");std::ifstream exists(argv[3]);need(!exists.good(),"fresh mutation output");std::ofstream out(argv[3]);for(auto&v:ls){for(size_t i=0;i<v.size();i++){if(i)out<<' ';out<<v[i];}out<<'\n';}return 0;}need(argc==1,"usage: no arguments OR mutate INPUT NEW MODE");need(power(59,30)==60,"extension irreducible");P g{F(0),F(10),false},u{F(37),F(14),false},s=chi(u);need(on(g,21,39)&&on(u,23,54)&&on(s,21,39)&&!s.o&&mul(g,31).o&&mul(s,31).o,"actual generators");need(P{pow(s.x,61),pow(s.y,61),false}==neg(s),"not minus Frobenius");auto src=group(g,21,39),tw=group(u,23,54);auto z=pairing(g,s);need(z&&*z!=F(1)&&pow(*z,31)==F(1),"pairing degeneracy");
std::cout<<"CM61PAIR 61 59 21 39 23 54 31\nGEN ";point(g);std::cout<<' ';point(u);std::cout<<' ';point(s);std::cout<<' '<<encode(*z)<<'\n';int shifted_checks=0;
for(int i=0;i<31;i++)for(int j=0;j<31;j++){P a=src[i],b=chi(tw[j]);need(on(b,21,39)&&mul(b,31).o&&(b.o||P{pow(b.x,61),pow(b.y,61),false}==neg(b)),"twist lift");auto value=pairing(a,b);need(value.has_value()&&pow(*value,31)==F(1),"pairing root");if(!a.o&&!b.o){need(*value!=F(1),"nontrivial pairing collapsed");P off=add(mul(a,2),mul(b,2));auto v=shifted(a,b,off);need(v&&*v==*value,"binary direct/shift mismatch");shifted_checks++;}std::cout<<"PAIR "<<i<<' '<<j<<' ';point(a);std::cout<<' ';point(tw[j]);std::cout<<' ';point(b);std::cout<<' '<<encode(*value)<<'\n';}
int hom=0,lifts=0;for(P a:src)for(P b:src){auto x=pairing(add(a,b),s),y=pairing(a,s),z2=pairing(b,s);need(x&&y&&z2&&*x==*y*(*z2),"actual source bilinearity");hom++;}for(P a:tw)for(P b:tw){need(chi(add(a,b,23))==add(chi(a),chi(b)),"actual twist lift homomorphism");lifts++;}
for(int i=0;i<31;i++){P q=src[i];auto v=pairing(q,s);int k=recover(q,g,s,*z);std::cout<<"REC "<<i<<' ';point(q);std::cout<<' '<<encode(*v)<<' '<<k<<'\n';}
P off=add(mul(g,2),mul(s,2));auto same=shifted(g,g,off);need(same&&*same==F(1)&&!pairing(g,g),"same subgroup/pole control");P wrong{F(59),F(),false},lift=chi(wrong);need(on(wrong,23,54)&&on(lift,21,39)&&!mul(lift,31).o,"wrong torsion control");std::cout<<"SAME "<<encode(*same)<<" 0 ";point(off);std::cout<<"\nWRONG ";point(wrong);std::cout<<' ';point(lift);std::cout<<"\nCHECK "<<961<<' '<<shifted_checks<<' '<<hom<<' '<<lifts<<" 31\nDEGREE NA\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 101;}return 0;}
